.slds-page-header_joined,
.slds-page-header.slds-has-bottom-magnet {
  border-bottom: $border-width-thin solid var(--slds-g-color-border-base-1, #{$page-header-joined-color-border});
  border-radius: $page-header-border-radius $page-header-border-radius 0 0;
  box-shadow: none;
}

// Overrides when inside a card
.slds-tabs_card .slds-page-header,
.slds-card .slds-page-header {
  border: 0;
  box-shadow: none;
  border-radius: $border-radius-medium;
}

// Lightning Design System 2.264.1
